--- /dev/null
+++ b/internal/hosted/agent/tools.go
@@ -0,0 +1,408 @@
+// Package agent contains the agentic review engine: the tools sub-agents may
+// call, and the bounds that keep those calls tenant-scoped, revision-pinned,
+// and read-only. Tool output is repository data, never instructions.
+package agent
+
+import (
+	"bytes"
+	"context"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"io"
+	"path"
+	"strings"
+	"unicode/utf8"
+
+	"px1/internal/hosted/graph"
+	"px1/internal/hosted/integrations/issues"
+)
+
+const (
+	MaxArgumentBytes  = 4 << 10
+	MaxToolOutput     = 16 << 10
+	MaxReadFileLines  = 400
+	MaxSearchResults  = 20
+	MaxHistoryCommits = 20
+	truncationNotice  = "\n[output truncated by px1]"
+)
+
+const (
+	ReadFile     = "read_file"
+	SearchCode   = "search_code"
+	GraphCallers = "graph_callers"
+	GraphCallees = "graph_callees"
+	GitBlame     = "git_blame"
+	GitLog       = "git_log"
+	ReadIssue    = "read_issue"
+)
+
+// Scope pins every call to one tenant, repository, and full head SHA. Linked
+// issues are the only issue keys read_issue may fetch, so injected text cannot
+// steer a sub-agent into reading unrelated tenant tickets.
+type Scope struct {
+	InstallationID int64
+	RepositoryID   int64
+	HeadSHA        string
+	LinkedIssues   []string
+}
+
+type ToolSpec struct {
+	Name        string          `json:"name"`
+	Description string          `json:"description"`
+	InputSchema json.RawMessage `json:"input_schema"`
+}
+
+type Call struct {
+	Name      string          `json:"name"`
+	Arguments json.RawMessage `json:"arguments"`
+}
+
+type Result struct {
+	Name      string `json:"name"`
+	Content   string `json:"content"`
+	Truncated bool   `json:"truncated,omitempty"`
+}
+
+type SearchHit struct {
+	Path      string `json:"path"`
+	StartLine int    `json:"start_line"`
+	EndLine   int    `json:"end_line"`
+	Snippet   string `json:"snippet"`
+	Source    string `json:"source"`
+}
+
+type BlameLine struct {
+	Line    int    `json:"line"`
+	Commit  string `json:"commit"`
+	Author  string `json:"author"`
+	Summary string `json:"summary"`
+}
+
+type Commit struct {
+	SHA     string `json:"sha"`
+	Author  string `json:"author"`
+	Date    string `json:"date"`
+	Summary string `json:"summary"`
+}
+
+// Backing stores. Implementations read the index, graph, and object store for
+// Scope.HeadSHA; none of them may check out or execute repository code.
+type (
+	FileReader interface {
+		ReadLines(ctx context.Context, scope Scope, path string, start, end int) (string, error)
+	}
+	CodeSearcher interface {
+		Search(ctx context.Context, scope Scope, query string, limit int) ([]SearchHit, error)
+	}
+	SymbolResolver interface {
+		ResolveSymbol(ctx context.Context, scope Scope, path, name string) (int64, bool, error)
+	}
+	History interface {
+		Blame(ctx context.Context, scope Scope, path string, start, end int) ([]BlameLine, error)
+		Log(ctx context.Context, scope Scope, path string, limit int) ([]Commit, error)
+	}
+)
+
+type Toolbox struct {
+	Files    FileReader
+	Search   CodeSearcher
+	Symbols  SymbolResolver
+	Graph    graph.Tools
+	History  History
+	Issues   issues.Tracker
+	MaxBytes int
+}
+
+// Specs lists only the tools whose backing store is configured, so a model is
+// never offered a tool that will fail on every call.
+func (t Toolbox) Specs() []ToolSpec {
+	var specs []ToolSpec
+	add := func(enabled bool, name, description, schema string) {
+		if enabled {
+			specs = append(specs, ToolSpec{Name: name, Description: description, InputSchema: json.RawMessage(schema)})
+		}
+	}
+	add(t.Files != nil, ReadFile, "Read a line range of one file at the reviewed head commit.",
+		`{"type":"object","additionalProperties":false,"required":["path","start_line","end_line"],"properties":{"path":{"type":"string"},"start_line":{"type":"integer","minimum":1},"end_line":{"type":"integer","minimum":1}}}`)
+	add(t.Search != nil, SearchCode, "Search the indexed repository by meaning and by exact text.",
+		`{"type":"object","additionalProperties":false,"required":["query"],"properties":{"query":{"type":"string","maxLength":200},"limit":{"type":"integer","minimum":1,"maximum":20}}}`)
+	graphSchema := `{"type":"object","additionalProperties":false,"required":["path","symbol"],"properties":{"path":{"type":"string"},"symbol":{"type":"string"},"depth":{"type":"integer","minimum":1,"maximum":2}}}`
+	add(t.Symbols != nil && t.Graph.Reader != nil, GraphCallers, "List symbols that call the named symbol, up to two hops.", graphSchema)
+	add(t.Symbols != nil && t.Graph.Reader != nil, GraphCallees, "List symbols the named symbol calls, up to two hops.", graphSchema)
+	add(t.History != nil, GitBlame, "Show the last commit to touch each line in a range.",
+		`{"type":"object","additionalProperties":false,"required":["path","start_line","end_line"],"properties":{"path":{"type":"string"},"start_line":{"type":"integer","minimum":1},"end_line":{"type":"integer","minimum":1}}}`)
+	add(t.History != nil, GitLog, "List recent commits that changed one file.",
+		`{"type":"object","additionalProperties":false,"required":["path"],"properties":{"path":{"type":"string"},"limit":{"type":"integer","minimum":1,"maximum":20}}}`)
+	add(t.Issues != nil, ReadIssue, "Read an issue linked from this pull request.",
+		`{"type":"object","additionalProperties":false,"required":["key"],"properties":{"key":{"type":"string"}}}`)
+	return specs
+}
+
+type lineRange struct {
+	Path      string `json:"path"`
+	StartLine int    `json:"start_line"`
+	EndLine   int    `json:"end_line"`
+}
+
+type symbolArgs struct {
+	Path   string `json:"path"`
+	Symbol string `json:"symbol"`
+	Depth  int    `json:"depth"`
+}
+
+// Dispatch validates one model-proposed call and runs it. Arguments are
+// decoded strictly; a call outside the scope or bounds returns an error the
+// caller can report back to the model instead of executing it.
+func (t Toolbox) Dispatch(ctx context.Context, scope Scope, call Call) (Result, error) {
+	if scope.InstallationID <= 0 || scope.RepositoryID <= 0 || !fullSHA(scope.HeadSHA) {
+		return Result{}, errors.New("tool calls require a tenant, repository, and full head SHA")
+	}
+	if len(call.Arguments) > MaxArgumentBytes {
+		return Result{}, fmt.Errorf("%s arguments exceed %d bytes", call.Name, MaxArgumentBytes)
+	}
+	var output any
+	var err error
+	switch call.Name {
+	case ReadFile:
+		output, err = t.readFile(ctx, scope, call.Arguments)
+	case SearchCode:
+		output, err = t.search(ctx, scope, call.Arguments)
+	case GraphCallers, GraphCallees:
+		output, err = t.graphNeighbors(ctx, scope, call)
+	case GitBlame:
+		output, err = t.blame(ctx, scope, call.Arguments)
+	case GitLog:
+		output, err = t.log(ctx, scope, call.Arguments)
+	case ReadIssue:
+		output, err = t.readIssue(ctx, scope, call.Arguments)
+	default:
+		return Result{}, fmt.Errorf("unknown tool %q", call.Name)
+	}
+	if err != nil {
+		return Result{}, fmt.Errorf("%s: %w", call.Name, err)
+	}
+	content, ok := output.(string)
+	if !ok {
+		encoded, err := json.Marshal(output)
+		if err != nil {
+			return Result{}, err
+		}
+		content = string(encoded)
+	}
+	content, truncated := truncate(content, t.maxBytes())
+	return Result{Name: call.Name, Content: content, Truncated: truncated}, nil
+}
+
+func (t Toolbox) readFile(ctx context.Context, scope Scope, raw json.RawMessage) (any, error) {
+	if t.Files == nil {
+		return nil, errUnavailable
+	}
+	var args lineRange
+	if err := decodeArgs(raw, &args); err != nil {
+		return nil, err
+	}
+	if err := validRange(&args); err != nil {
+		return nil, err
+	}
+	return t.Files.ReadLines(ctx, scope, args.Path, args.StartLine, args.EndLine)
+}
+
+func (t Toolbox) search(ctx context.Context, scope Scope, raw json.RawMessage) (any, error) {
+	if t.Search == nil {
+		return nil, errUnavailable
+	}
+	var args struct {
+		Query string `json:"query"`
+		Limit int    `json:"limit"`
+	}
+	if err := decodeArgs(raw, &args); err != nil {
+		return nil, err
+	}
+	args.Query = strings.TrimSpace(args.Query)
+	if args.Query == "" || len(args.Query) > 200 {
+		return nil, errors.New("query must be 1 to 200 bytes")
+	}
+	args.Limit = clamp(args.Limit, 10, MaxSearchResults)
+	hits, err := t.Search.Search(ctx, scope, args.Query, args.Limit)
+	if err != nil {
+		return nil, err
+	}
+	if len(hits) > args.Limit {
+		hits = hits[:args.Limit]
+	}
+	return hits, nil
+}
+
+func (t Toolbox) graphNeighbors(ctx context.Context, scope Scope, call Call) (any, error) {
+	if t.Symbols == nil || t.Graph.Reader == nil {
+		return nil, errUnavailable
+	}
+	var args symbolArgs
+	if err := decodeArgs(call.Arguments, &args); err != nil {
+		return nil, err
+	}
+	clean, err := repositoryPath(args.Path)
+	if err != nil {
+		return nil, err
+	}
+	if strings.TrimSpace(args.Symbol) == "" || len(args.Symbol) > 200 {
+		return nil, errors.New("symbol must be 1 to 200 bytes")
+	}
+	id, found, err := t.Symbols.ResolveSymbol(ctx, scope, clean, args.Symbol)
+	if err != nil {
+		return nil, err
+	}
+	if !found {
+		return fmt.Sprintf("No indexed symbol %q in %s at this revision.", args.Symbol, clean), nil
+	}
+	query := graph.ToolQuery{InstallationID: scope.InstallationID, RepositoryID: scope.RepositoryID, SymbolID: id, Depth: args.Depth, Limit: 50}
+	if call.Name == GraphCallers {
+		return t.Graph.Callers(ctx, query)
+	}
+	return t.Graph.Callees(ctx, query)
+}
+
+func (t Toolbox) blame(ctx context.Context, scope Scope, raw json.RawMessage) (any, error) {
+	if t.History == nil {
+		return nil, errUnavailable
+	}
+	var args lineRange
+	if err := decodeArgs(raw, &args); err != nil {
+		return nil, err
+	}
+	if err := validRange(&args); err != nil {
+		return nil, err
+	}
+	return t.History.Blame(ctx, scope, args.Path, args.StartLine, args.EndLine)
+}
+
+func (t Toolbox) log(ctx context.Context, scope Scope, raw json.RawMessage) (any, error) {
+	if t.History == nil {
+		return nil, errUnavailable
+	}
+	var args struct {
+		Path  string `json:"path"`
+		Limit int    `json:"limit"`
+	}
+	if err := decodeArgs(raw, &args); err != nil {
+		return nil, err
+	}
+	clean, err := repositoryPath(args.Path)
+	if err != nil {
+		return nil, err
+	}
+	limit := clamp(args.Limit, 10, MaxHistoryCommits)
+	commits, err := t.History.Log(ctx, scope, clean, limit)
+	if err != nil {
+		return nil, err
+	}
+	if len(commits) > limit {
+		commits = commits[:limit]
+	}
+	return commits, nil
+}
+
+func (t Toolbox) readIssue(ctx context.Context, scope Scope, raw json.RawMessage) (any, error) {
+	if t.Issues == nil {
+		return nil, errUnavailable
+	}
+	var args struct {
+		Key string `json:"key"`
+	}
+	if err := decodeArgs(raw, &args); err != nil {
+		return nil, err
+	}
+	linked := false
+	for _, key := range scope.LinkedIssues {
+		linked = linked || key == args.Key
+	}
+	if !linked {
+		return nil, fmt.Errorf("issue %q is not linked from this pull request", args.Key)
+	}
+	issue, err := t.Issues.FetchIssue(ctx, scope.InstallationID, args.Key)
+	if err != nil {
+		return nil, err
+	}
+	return struct {
+		Key                string   `json:"key"`
+		Title              string   `json:"title"`
+		Description        string   `json:"description"`
+		AcceptanceCriteria []string `json:"acceptance_criteria,omitempty"`
+		URL                string   `json:"url"`
+	}{issue.Key, issue.Title, issue.Description, issue.AcceptanceCriteria, issue.URL}, nil
+}
+
+var errUnavailable = errors.New("tool is not configured for this review")
+
+func decodeArgs(raw json.RawMessage, target any) error {
+	decoder := json.NewDecoder(bytes.NewReader(raw))
+	decoder.DisallowUnknownFields()
+	if err := decoder.Decode(target); err != nil {
+		return fmt.Errorf("invalid arguments: %w", err)
+	}
+	if _, err := decoder.Token(); err != io.EOF {
+		return errors.New("invalid arguments: trailing data")
+	}
+	return nil
+}
+
+func validRange(args *lineRange) error {
+	clean, err := repositoryPath(args.Path)
+	if err != nil {
+		return err
+	}
+	args.Path = clean
+	if args.StartLine < 1 || args.EndLine < args.StartLine {
+		return errors.New("line range is invalid")
+	}
+	if args.EndLine-args.StartLine+1 > MaxReadFileLines {
+		return fmt.Errorf("line range exceeds %d lines", MaxReadFileLines)
+	}
+	return nil
+}
+
+func repositoryPath(value string) (string, error) {
+	clean := path.Clean(strings.ReplaceAll(value, "\\", "/"))
+	if value == "" || strings.HasPrefix(clean, "/") || clean == "." || clean == ".." || strings.HasPrefix(clean, "../") || strings.ContainsRune(value, 0) {
+		return "", errors.New("path must be repository-relative")
+	}
+	return clean, nil
+}
+
+func truncate(content string, limit int) (string, bool) {
+	if len(content) <= limit {
+		return content, false
+	}
+	cut := limit - len(truncationNotice)
+	for cut > 0 && !utf8.RuneStart(content[cut]) {
+		cut--
+	}
+	return content[:cut] + truncationNotice, true
+}
+
+func (t Toolbox) maxBytes() int {
+	if t.MaxBytes <= 0 || t.MaxBytes > MaxToolOutput {
+		return MaxToolOutput
+	}
+	return t.MaxBytes
+}
+
+func clamp(value, fallback, maximum int) int {
+	if value <= 0 {
+		return fallback
+	}
+	return min(value, maximum)
+}
+
+func fullSHA(value string) bool {
+	if len(value) != 40 {
+		return false
+	}
+	for _, r := range value {
+		if !((r >= '0' && r <= '9') || (r >= 'a' && r <= 'f')) {
+			return false
+		}
+	}
+	return true
+}

diff --git a/internal/hosted/agent/tools_test.go b/internal/hosted/agent/tools_test.go
new file mode 100644
index 0000000..b757408
--- /dev/null
+++ b/internal/hosted/agent/tools_test.go
@@ -0,0 +1,189 @@
+package agent
+
+import (
+	"context"
+	"encoding/json"
+	"strings"
+	"testing"
+	"unicode/utf8"
+
+	"px1/internal/hosted/graph"
+	"px1/internal/hosted/integrations/issues"
+)
+
+var scope = Scope{InstallationID: 7, RepositoryID: 9, HeadSHA: strings.Repeat("a", 40), LinkedIssues: []string{"ENG-12"}}
+
+type fakeFiles struct{ gotPath string }
+
+func (f *fakeFiles) ReadLines(_ context.Context, s Scope, path string, start, end int) (string, error) {
+	f.gotPath = path
+	return strings.Repeat("é", 20_000), nil
+}
+
+type fakeSearch struct{}
+
+func (fakeSearch) Search(_ context.Context, _ Scope, query string, limit int) ([]SearchHit, error) {
+	hits := make([]SearchHit, 50)
+	for i := range hits {
+		hits[i] = SearchHit{Path: "a.go", StartLine: i + 1, EndLine: i + 1, Snippet: query, Source: "ripgrep"}
+	}
+	return hits, nil
+}
+
+type fakeSymbols struct{}
+
+func (fakeSymbols) ResolveSymbol(_ context.Context, _ Scope, path, name string) (int64, bool, error) {
+	return 42, name == "Charge", nil
+}
+
+type fakeGraph struct{ gotTenant, gotRepo int64 }
+
+func (g *fakeGraph) Neighbors(_ context.Context, tenant, repo int64, ids []int64, direction graph.Direction, _ []string) ([]graph.ToolEdge, error) {
+	g.gotTenant, g.gotRepo = tenant, repo
+	caller := graph.ToolSymbol{ID: 5, Path: "api/handler.go", Kind: "function", Name: "Handle"}
+	return []graph.ToolEdge{{Source: caller, Target: graph.ToolSymbol{ID: ids[0]}, Kind: "calls"}}, nil
+}
+
+type fakeIssues struct{ fetched []string }
+
+func (f *fakeIssues) FetchIssue(_ context.Context, _ int64, key string) (issues.Issue, error) {
+	f.fetched = append(f.fetched, key)
+	return issues.Issue{Key: key, Title: "Refunds", URL: "https://linear.app/x/issue/" + key}, nil
+}
+
+func call(name, arguments string) Call {
+	return Call{Name: name, Arguments: json.RawMessage(arguments)}
+}
+
+func TestSpecsOfferOnlyConfiguredTools(t *testing.T) {
+	if specs := (Toolbox{}).Specs(); len(specs) != 0 {
+		t.Fatalf("empty toolbox offered %d tools", len(specs))
+	}
+	specs := Toolbox{Files: &fakeFiles{}, Search: fakeSearch{}}.Specs()
+	if len(specs) != 2 || specs[0].Name != ReadFile || specs[1].Name != SearchCode {
+		t.Fatalf("unexpected specs: %#v", specs)
+	}
+	for _, spec := range specs {
+		var schema map[string]any
+		if err := json.Unmarshal(spec.InputSchema, &schema); err != nil || schema["additionalProperties"] != false {
+			t.Fatalf("%s schema must be strict JSON: %v", spec.Name, err)
+		}
+	}
+}
+
+func TestDispatchRequiresAPinnedTenantScope(t *testing.T) {
+	box := Toolbox{Files: &fakeFiles{}}
+	for _, bad := range []Scope{{RepositoryID: 9, HeadSHA: scope.HeadSHA}, {InstallationID: 7, RepositoryID: 9, HeadSHA: "main"}} {
+		if _, err := box.Dispatch(context.Background(), bad, call(ReadFile, `{"path":"a.go","start_line":1,"end_line":2}`)); err == nil {
+			t.Fatalf("scope %#v accepted", bad)
+		}
+	}
+}
+
+func TestReadFileRejectsEscapesUnknownFieldsAndHugeRanges(t *testing.T) {
+	box := Toolbox{Files: &fakeFiles{}}
+	for _, arguments := range []string{
+		`{"path":"../secrets","start_line":1,"end_line":2}`,
+		`{"path":"/etc/passwd","start_line":1,"end_line":2}`,
+		`{"path":"a.go","start_line":1,"end_line":2,"shell":"rm"}`,
+		`{"path":"a.go","start_line":5,"end_line":4}`,
+		`{"path":"a.go","start_line":1,"end_line":401}`,
+		`{"path":"a.go","start_line":1,"end_line":2} {}`,
+	} {
+		if _, err := box.Dispatch(context.Background(), scope, call(ReadFile, arguments)); err == nil {
+			t.Fatalf("%s accepted", arguments)
+		}
+	}
+	if _, err := box.Dispatch(context.Background(), scope, call("run_shell", `{}`)); err == nil {
+		t.Fatal("unknown tool accepted")
+	}
+}
+
+func TestOutputIsTruncatedOnARuneBoundary(t *testing.T) {
+	files := &fakeFiles{}
+	result, err := Toolbox{Files: files}.Dispatch(context.Background(), scope, call(ReadFile, `{"path":"./pkg//a.go","start_line":1,"end_line":2}`))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if files.gotPath != "pkg/a.go" || !result.Truncated || len(result.Content) > MaxToolOutput || !utf8.ValidString(result.Content) || !strings.HasSuffix(result.Content, truncationNotice) {
+		t.Fatalf("path=%q truncated=%v len=%d", files.gotPath, result.Truncated, len(result.Content))
+	}
+}
+
+func TestSearchCapsResults(t *testing.T) {
+	result, err := Toolbox{Search: fakeSearch{}}.Dispatch(context.Background(), scope, call(SearchCode, `{"query":"refund","limit":500}`))
+	if err != nil {
+		t.Fatal(err)
+	}
+	var hits []SearchHit
+	if err := json.Unmarshal([]byte(result.Content), &hits); err != nil || len(hits) != MaxSearchResults {
+		t.Fatalf("hits=%d err=%v", len(hits), err)
+	}
+}
+
+func TestGraphToolsResolveSymbolsWithinTheTenant(t *testing.T) {
+	reader := &fakeGraph{}
+	box := Toolbox{Symbols: fakeSymbols{}, Graph: graph.Tools{Reader: reader}}
+	result, err := box.Dispatch(context.Background(), scope, call(GraphCallers, `{"path":"billing/charge.go","symbol":"Charge","depth":2}`))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if reader.gotTenant != 7 || reader.gotRepo != 9 || !strings.Contains(result.Content, "Handle") {
+		t.Fatalf("tenant=%d repo=%d content=%s", reader.gotTenant, reader.gotRepo, result.Content)
+	}
+	missing, err := box.Dispatch(context.Background(), scope, call(GraphCallees, `{"path":"a.go","symbol":"Nope"}`))
+	if err != nil || !strings.Contains(missing.Content, "No indexed symbol") {
+		t.Fatalf("missing symbol: %#v %v", missing, err)
+	}
+	if _, err := box.Dispatch(context.Background(), scope, call(GraphCallers, `{"path":"a.go","symbol":"Charge","depth":3}`)); err == nil {
+		t.Fatal("three-hop traversal accepted")
+	}
+}
+
+func TestReadIssueOnlyFetchesLinkedIssues(t *testing.T) {
+	tracker := &fakeIssues{}
+	box := Toolbox{Issues: tracker}
+	if _, err := box.Dispatch(context.Background(), scope, call(ReadIssue, `{"key":"SEC-1"}`)); err == nil {
+		t.Fatal("unlinked issue fetched")
+	}
+	result, err := box.Dispatch(context.Background(), scope, call(ReadIssue, `{"key":"ENG-12"}`))
+	if err != nil || !strings.Contains(result.Content, "Refunds") || len(tracker.fetched) != 1 {
+		t.Fatalf("result=%#v err=%v fetched=%v", result, err, tracker.fetched)
+	}
+}
+
+func TestUnconfiguredToolsFailClosed(t *testing.T) {
+	for _, name := range []string{ReadFile, SearchCode, GraphCallers, GitBlame, GitLog, ReadIssue} {
+		if _, err := (Toolbox{}).Dispatch(context.Background(), scope, call(name, `{}`)); err == nil {
+			t.Fatalf("%s ran without a backing store", name)
+		}
+	}
+}
+
+type fakeHistory struct{ gotLimit int }
+
+func (h *fakeHistory) Blame(_ context.Context, _ Scope, path string, start, end int) ([]BlameLine, error) {
+	return []BlameLine{{Line: start, Commit: strings.Repeat("b", 40), Author: "dev", Summary: "add " + path}}, nil
+}
+
+func (h *fakeHistory) Log(_ context.Context, _ Scope, _ string, limit int) ([]Commit, error) {
+	h.gotLimit = limit
+	return make([]Commit, 100), nil
+}
+
+func TestHistoryToolsAreBounded(t *testing.T) {
+	history := &fakeHistory{}
+	box := Toolbox{History: history}
+	blame, err := box.Dispatch(context.Background(), scope, call(GitBlame, `{"path":"a.go","start_line":3,"end_line":3}`))
+	if err != nil || !strings.Contains(blame.Content, "add a.go") {
+		t.Fatalf("blame=%#v err=%v", blame, err)
+	}
+	log, err := box.Dispatch(context.Background(), scope, call(GitLog, `{"path":"a.go","limit":1000}`))
+	if err != nil {
+		t.Fatal(err)
+	}
+	var commits []Commit
+	if err := json.Unmarshal([]byte(log.Content), &commits); err != nil || history.gotLimit != MaxHistoryCommits || len(commits) != MaxHistoryCommits {
+		t.Fatalf("limit=%d commits=%d err=%v", history.gotLimit, len(commits), err)
+	}
+}
